declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\Shared;

/**
 * Reads expression arguments from PHP-Parser call argument lists.
 */
final class CallArgumentResolver
{
    /**
     * @param array<array-key, \PhpParser\Node\Arg|\PhpParser\Node\ArgPlaceholder|\PhpParser\Node\VariadicPlaceholder> $args
     */
    public function valueAt(array $args, int $position): ?\PhpParser\Node\Expr
    {
        $arg = $args[$position] ?? null;

        return $arg instanceof \PhpParser\Node\Arg ? $arg->value : null;
    }

    /**
     * @param array<array-key, \PhpParser\Node\Arg|\PhpParser\Node\ArgPlaceholder|\PhpParser\Node\VariadicPlaceholder> $args
     */
    public function firstValue(array $args): ?\PhpParser\Node\Expr
    {
        return $this->valueAt($args, 0);
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\Shared\Path;

/**
 * Normalizes filesystem paths for PHPStan path-based rules.
 */
final class RulePathNormalizer
{
    /**
     * Converts path separators to the rule-internal slash format.
     */
    public function normalize(string $path): string
    {
        return str_replace('\\', '/', $path);
    }
}
